/// Every Live TV channel: the built-ins wearing their reviewed art, then the extras.
List<HardcodedChannel> get liveChannels => [
      for (final c in HardcodedChannels.all) _withArt(c),
      ...extraChannels,
    ];

/// The original list's backdrops are mostly tv-logo PNGs: a logo cropped as a poster looks broken, so
/// those are dropped and the channel falls back to its logo tile.
String? _realPoster(String? url) => url == null || url.contains('tv-logo') ? null : url;

HardcodedChannel _withArt(HardcodedChannel c) {
  final a = channelArt[c.id];
  return HardcodedChannel(
    id: c.id,
    name: c.name,
    short: c.short,
    category: c.category,
    keywords: c.keywords,
    exclude: c.exclude,
    gradient: c.gradient,
    iconUrl: a?.logo ?? c.iconUrl,
    backdropUrl: a?.poster ?? _realPoster(c.backdropUrl),
  );
}
